.","difficulty":{"cefr":"A1","speaking_target_seconds":60,"stage":"absolute_beginner","target_words_per_minute":45},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["greeting","introducing oneself","asking a name","asking for repetition"],"grammar":["Subject pronouns","Present tense of be","Basic affirmative word order","A and an"],"pronunciation":[{"description":"Clear names, greetings, and final consonants.","focus":"clarity","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["Hello.","Hi, I am new.","Goodbye. See you.","My name is...","What is your name?","How do you spell it?","I am from...","Where are you from?","I live in...","I speak...","Do you speak English?","A little.","Nice to meet you.","Nice to meet you too.","Welcome to the class.","This is a book.","That is the board.","She is my classmate.","Open your book.","Please listen."],"target_word_count":50,"themes":["greetings","names","countries","languages","classroom instructions"]}},"learner_identity":"I can introduce myself and communicate in my first English class.","learning_objectives":[{"can_do_statement":"I can introduce myself and communicate in my first English class.","measurable_success":"Completes the final speaking mission for My First English Class.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"c