VALUES ('703816f3-fc86-5270-9363-471f959f2711', NULL, 'Hello and Goodbye', 'Greet a teacher and say goodbye politely.

The learner uses English in a realistic study situation focused on hello and goodbye.', 0, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Hello.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Hello.","Hi, I am new.","Goodbye. See you."],"points":10,"prompt":"Which phrase best helps you: greet a teacher and say goodbye politely.","type":"multiple_choice"},{"answer":["Hello.","Hi, I am new.","Goodbye. See you."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Hello.","Hi, I am new.","Goodbye. See you."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Say hello, introduce yourself, and say goodbye.","type":"recording"}],"final_task":{"learner_instruction":"Say hello, introduce yourself, and say goodbye. Speak for at least 20 seconds.","minimum_seconds":20,"required_language":["Hello.","Hi, I am new."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Say hello, introduce yourself, and say goodbye.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L01","lesson_number":1,"mission":"Greet a teacher and say goodbye politely.","objectives":["Use key words and phrases to greet a teacher and say goodbye politely.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on hello and goodbye.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to greet a teacher and say goodbye politely.","examples":["Hello.","Hi, I am new.","Goodbye. See you."],"pattern":"be: I am","point":"be: I am"}],"phrases":[{"audio_key":"a1_study_t01_l01_phrase_01","example":"Hello.","formality":"neutral","phrase":"Hello.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l01_phrase_02","example":"Hi, I am new.","formality":"neutral","phrase":"Hi, I am new.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l01_phrase_03","example":"Goodbye. See you.","formality":"neutral","phrase":"Goodbye. See you.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l01_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"Hello.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l01_vocab_01","example":"I use the word ''hello'' in this lesson.","image_key":"a1_study_t01_l01_vocab_01","meaning":"A key word used in this lesson: hello.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''hello''.","word":"hello"},{"audio_key":"a1_study_t01_l01_vocab_02","example":"I use the word ''hi'' in this lesson.","image_key":"a1_study_t01_l01_vocab_02","meaning":"A key word used in this lesson: hi.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''hi''.","word":"hi"},{"audio_key":"a1_study_t01_l01_vocab_03","example":"I use the word ''goodbye'' in this lesson.","image_key":"a1_study_t01_l01_vocab_03","meaning":"A key word used in this lesson: goodbye.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''goodbye''.","word":"goodbye"},{"audio_key":"a1_study_t01_l01_vocab_04","example":"I use the word ''teacher'' in this lesson.","image_key":"a1_study_t01_l01_vocab_04","meaning":"A key word used in this lesson: teacher.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''teacher''.","word":"teacher"},{"audio_key":"a1_study_t01_l01_vocab_05","example":"I use the word ''student'' in this lesson.","image_key":"a1_study_t01_l01_vocab_05","meaning":"A key word used in this lesson: student.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''student''.","word":"student"}]},"title":"Hello and Goodbye"}'::jsonb, NOW(), NOW())
