VALUES ('d9d45178-0d12-5348-8a40-0e4a427528a5', NULL, 'My Name Is...', 'Say your name and ask another person''s name.

The learner uses English in a realistic study situation focused on my name is....', 1, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"My name is...","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["My name is...","What is your name?","How do you spell it?"],"points":10,"prompt":"Which phrase best helps you: say your name and ask another person''s name.","type":"multiple_choice"},{"answer":["My name is...","What is your name?","How do you spell it?"],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["My name is...","What is your name?","How do you spell it?"],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Exchange names with a new classmate.","type":"recording"}],"final_task":{"learner_instruction":"Exchange names with a new classmate. Speak for at least 25 seconds.","minimum_seconds":25,"required_language":["My name is...","What is your name?"],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Exchange names with a new classmate.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L02","lesson_number":2,"mission":"Say your name and ask another person''s name.","objectives":["Use key words and phrases to say your name and ask another person''s name.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on my name is....","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to say your name and ask another person''s name.","examples":["My name is...","What is your name?","How do you spell it?"],"pattern":"be questions: What is...?","point":"be questions: What is...?"}],"phrases":[{"audio_key":"a1_study_t01_l02_phrase_01","example":"My name is...","formality":"neutral","phrase":"My name is...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l02_phrase_02","example":"What is your name?","formality":"neutral","phrase":"What is your name?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l02_phrase_03","example":"How do you spell it?","formality":"neutral","phrase":"How do you spell it?","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l02_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"My name is...","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l02_vocab_01","example":"I use the word ''name'' in this lesson.","image_key":"a1_study_t01_l02_vocab_01","meaning":"A key word used in this lesson: name.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''name''.","word":"name"},{"audio_key":"a1_study_t01_l02_vocab_02","example":"I use the word ''first'' in this lesson.","image_key":"a1_study_t01_l02_vocab_02","meaning":"A key word used in this lesson: first.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''first''.","word":"first"},{"audio_key":"a1_study_t01_l02_vocab_03","example":"I use the word ''last'' in this lesson.","image_key":"a1_study_t01_l02_vocab_03","meaning":"A key word used in this lesson: last.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''last''.","word":"last"},{"audio_key":"a1_study_t01_l02_vocab_04","example":"I use the word ''spell'' in this lesson.","image_key":"a1_study_t01_l02_vocab_04","meaning":"A key word used in this lesson: spell.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''spell''.","word":"spell"},{"audio_key":"a1_study_t01_l02_vocab_05","example":"I use the word ''please'' in this lesson.","image_key":"a1_study_t01_l02_vocab_05","meaning":"A key word used in this lesson: please.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''please''.","word":"please"}]},"title":"My Name Is..."}'::jsonb, NOW(), NOW())
