INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('bc841ef2-ba50-58d1-8a61-0fb36cee7e42', NULL, 'I Am From...', 'Say your country and ask where another person is from.

The learner uses English in a realistic study situation focused on i am from....', 2, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"I am from...","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["I am from...","Where are you from?","I live in..."],"points":10,"prompt":"Which phrase best helps you: say your country and ask where another person is from.","type":"multiple_choice"},{"answer":["I am from...","Where are you from?","I live in..."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["I am from...","Where are you from?","I live in..."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Tell a classmate where you are from.","type":"recording"}],"final_task":{"learner_instruction":"Tell a classmate where you are from. Speak for at least 30 seconds.","minimum_seconds":30,"required_language":["I am from...","Where are you from?"],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Tell a classmate where you are from.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L03","lesson_number":3,"mission":"Say your country and ask where another person is from.","objectives":["Use key words and phrases to say your country and ask where another person is from.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on i am from....","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to say your country and ask where another person is from.","examples":["I am from...","Where are you from?","I live in..."],"pattern":"be + from","point":"be + from"}],"phrases":[{"audio_key":"a1_study_t01_l03_phrase_01","example":"I am from...","formality":"neutral","phrase":"I am from...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l03_phrase_02","example":"Where are you from?","formality":"neutral","phrase":"Where are you from?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l03_phrase_03","example":"I live in...","formality":"neutral","phrase":"I live in...","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l03_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"I am from...","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l03_vocab_01","example":"I use the word ''country'' in this lesson.","image_key":"a1_study_t01_l03_vocab_01","meaning":"A key word used in this lesson: country.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''country''.","word":"country"},{"audio_key":"a1_study_t01_l03_vocab_02","example":"I use the word ''from'' in this lesson.","image_key":"a1_study_t01_l03_vocab_02","meaning":"A key word used in this lesson: from.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''from''.","word":"from"},{"audio_key":"a1_study_t01_l03_vocab_03","example":"I use the word ''city'' in this lesson.","image_key":"a1_study_t01_l03_vocab_03","meaning":"A key word used in this lesson: city.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''city''.","word":"city"},{"audio_key":"a1_study_t01_l03_vocab_04","example":"I use the word ''live'' in this lesson.","image_key":"a1_study_t01_l03_vocab_04","meaning":"A key word used in this lesson: live.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''live''.","word":"live"},{"audio_key":"a1_study_t01_l03_vocab_05","example":"I use the word ''capital'' in this lesson.","image_key":"a1_study_t01_l03_vocab_05","meaning":"A key word used in this lesson: capital.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''capital''.","word":"capital"}]},"title":"I Am From..."}'::jsonb, NOW(), NOW())
