pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Talk about the languages you speak.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L04","lesson_number":4,"mission":"Say which languages you speak.","objectives":["Use key words and phrases to say which languages you speak.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on i speak....","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to say which languages you speak.","examples":["I speak...","Do you speak English?","A little."],"pattern":"present simple: speak","point":"present simple: speak"}],"phrases":[{"audio_key":"a1_study_t01_l04_phrase_01","example":"I speak...","formality":"neutral","phrase":"I speak...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l04_phrase_02","example":"Do you speak English?","formality":"neutral","phrase":"Do you speak English?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l04_phrase_03","example":"A little.","formality":"neutral","phrase":"A little.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l04_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"I speak...","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l04_vocab_01","example":"I use the word ''language'' in this lesson.","image_key":"a1_study_t01_l04_vocab_01","meaning":"A key word used in this lesson: language.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''language''.","word":"language"},{"audio_key":"a1_study_t01_l04_vocab_02","example":"I use the word ''speak'' in this lesson.","image_key":"a1_study_t01_l04_vocab_02","meaning":"A key word used in this lesson: speak.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''speak''.","word":"speak"},{"audio_key":"a1_study_t01_l04_vocab_03","example":"I use the word ''English'' in this lesson.","image_key":"a1_study_t01_l04_vocab_03","meaning":"A key word used in this lesson: English.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''English''.","word":"English"},{"audio_key":"a1_study_t01_l04_vocab_04","example":"I use the word ''Russian'' in this lesson.","image_key":"a1_study_t01_l04_vocab_04","meaning":"A key word used in this lesson: Russian.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''Russian''.","word":"Russian"},{"audio_key":"a1_study_t01_l04_vocab_05","example":"I use the word ''Chinese'' in this lesson.","image_key":"a1_study_t01_l04_vocab_05","meaning":"A key word used in this lesson: Chinese.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''Chinese''.","word":"Chinese"}]},"title":"I Speak..."}'::jsonb, NOW(), NOW())
