INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('5a8e8117-1889-5e92-af3b-0b063ded65fe', NULL, 'Nice to Meet You', 'Complete a polite first meeting.

The learner uses English in a realistic study situation focused on nice to meet you.', 4, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Nice to meet you.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Nice to meet you.","Nice to meet you too.","Welcome to the class."],"points":10,"prompt":"Which phrase best helps you: complete a polite first meeting.","type":"multiple_choice"},{"answer":["Nice to meet you.","Nice to meet you too.","Welcome to the class."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Nice to meet you.","Nice to meet you too.","Welcome to the class."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Complete a four-turn first meeting.","type":"recording"}],"final_task":{"learner_instruction":"Complete a four-turn first meeting. Speak for at least 40 seconds.","minimum_seconds":40,"required_language":["Nice to meet you.","Nice to meet you too."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Complete a four-turn first meeting.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L05","lesson_number":5,"mission":"Complete a polite first meeting.","objectives":["Use key words and phrases to complete a polite first meeting.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on nice to meet you.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to complete a polite first meeting.","examples":["Nice to meet you.","Nice to meet you too.","Welcome to the class."],"pattern":"fixed social expressions","point":"fixed social expressions"}],"phrases":[{"audio_key":"a1_study_t01_l05_phrase_01","example":"Nice to meet you.","formality":"neutral","phrase":"Nice to meet you.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l05_phrase_02","example":"Nice to meet you too.","formality":"neutral","phrase":"Nice to meet you too.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l05_phrase_03","example":"Welcome to the class.","formality":"neutral","phrase":"Welcome to the class.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l05_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"Nice to meet you.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l05_vocab_01","example":"I use the word ''meet'' in this lesson.","image_key":"a1_study_t01_l05_vocab_01","meaning":"A key word used in this lesson: meet.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''meet''.","word":"meet"},{"audio_key":"a1_study_t01_l05_vocab_02","example":"I use the word ''nice'' in this lesson.","image_key":"a1_study_t01_l05_vocab_02","meaning":"A key word used in this lesson: nice.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''nice''.","word":"nice"},{"audio_key":"a1_study_t01_l05_vocab_03","example":"I use the word ''too'' in this lesson.","image_key":"a1_study_t01_l05_vocab_03","meaning":"A key word used in this lesson: too.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''too''.","word":"too"},{"audio_key":"a1_study_t01_l05_vocab_04","example":"I use the word ''welcome'' in this lesson.","image_key":"a1_study_t01_l05_vocab_04","meaning":"A key word used in this lesson: welcome.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''welcome''.","word":"welcome"},{"audio_key":"a1_study_t01_l05_vocab_05","example":"I use the word ''class'' in this lesson.","image_key":"a1_study_t01_l05_vocab_05","meaning":"A key word used in this lesson: class.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''class''.","word":"class"}]},"title":"Nice to Meet You"}'::jsonb, NOW(), NOW())
