INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('1ffc148b-8f6e-592c-9637-bad7369101dd', '5a8e8117-1889-5e92-af3b-0b063ded65fe', 'activity', 'AI Speaking Mission', '{"activity_id":"ACT_09","activity_type":"ai_roleplay","ai_config":{"allowed_vocabulary":["nice","to","meet","you","nice","to","meet","you","too","welcome","to","the","class"],"correction_style":"hint_first","difficulty_adjustment":"adaptive_by_confidence","learner_level":"A1","max_turns":8,"opening_message":"Nice to meet you.","persona":"Warm, patient, encouraging, and concise. Use only beginner-friendly English.","role":"classmate or teacher in the lesson scenario","scoring_rubric":[{"criterion":"task_completion","description":"The learner completes the communication mission.","weight":0.4},{"criterion":"intelligibility","description":"The learner is understandable.","weight":0.3},{"criterion":"target_language","description":"The learner uses lesson words and phrases.","weight":0.3}],"system_prompt":"You are an A1 English speaking partner. Help the learner complete this mission: Complete a four-turn first meeting. Use short sentences, one question at a time, and familiar vocabulary. Do not give long grammar explanations. Recast serious errors gently and praise successful communication.","target_phrases":["Nice to meet you.","Nice to meet you too.","Welcome to the class."]},"content":{"required_phrases":["Nice to meet you.","Nice to meet you too."],"scenario":"Complete a four-turn first meeting.","success_message":"Mission complete! You communicated successfully."},"estimated_seconds":180,"instructions":"Complete the mission with the AI partner.","order":9,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"source_activity":{"activity_id":"ACT_09","ai_config":{"allowed_vocabulary":["nice","to","meet","you","nice","to","meet","you","too","welcome","to","the","class"],"correction_style":"hint_first","difficulty_adjustment":"adaptive_by_confidence","learner_level":"A1","max_turns":8,"opening_message":"Nice to meet you.","persona":"Warm, patient, encouraging, and concise. Use only beginner-friendly English.","role":"classmate or teacher in the lesson scenario","scoring_rubric":[{"criterion":"task_completion","description":"The learner completes the communication mission.","weight":0.4},{"criterion":"intelligibility","description":"The learner is understandable.","weight":0.3},{"criterion":"target_language","description":"The learner uses lesson words and phrases.","weight":0.3}],"system_prompt":"You are an A1 English speaking partner. Help the learner complete this mission: Complete a four-turn first meeting. Use short sentences, one question at a time, and familiar vocabulary. Do not give long grammar explanations. Recast serious errors gently and praise successful communication.","target_phrases":["Nice to meet you.","Nice to meet you too.","Welcome to the class."]},"content":{"required_phrases":["Nice to meet you.","Nice to meet you too."],"scenario":"Complete a four-turn first meeting.","success_message":"Mission complete! You communicated successfully."},"estimated_seconds":180,"instructions":"Complete the mission with the AI partner.","order":9,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"success_criteria":["The learner completes the mission.","The learner uses at least two target phrases."],"title":"AI Speaking Mission","type":"ai_roleplay"},"success_criteria":["The learner completes the mission.","The learner uses at least two target phrases."],"target_phrases":["Nice to meet you.","Nice to meet you too.","Welcome to the class."],"target_vocabulary":["meet","nice","too","welcome","class"],"title":"AI Speaking Mission","type":"ai_roleplay"}'::jsonb, 8, NOW(), NOW())
