INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e1ff2635-1c09-5a90-ad8e-d494ed629629', '54a2c0ef-b733-55b0-bb94-7a5d27068e67', 'activity', 'AI Speaking Mission', '{"activity_id":"ACT_09","activity_type":"ai_roleplay","ai_config":{"allowed_vocabulary":["this","is","a","book","that","is","the","board","she","is","my","classmate"],"correction_style":"hint_first","difficulty_adjustment":"adaptive_by_confidence","learner_level":"A1","max_turns":8,"opening_message":"This is a book.","persona":"Warm, patient, encouraging, and concise. Use only beginner-friendly English.","role":"classmate or teacher in the lesson scenario","scoring_rubric":[{"criterion":"task_completion","description":"The learner completes the communication mission.","weight":0.4},{"criterion":"intelligibility","description":"The learner is understandable.","weight":0.3},{"criterion":"target_language","description":"The learner uses lesson words and phrases.","weight":0.3}],"system_prompt":"You are an A1 English speaking partner. Help the learner complete this mission: Name five things in the classroom. Use short sentences, one question at a time, and familiar vocabulary. Do not give long grammar explanations. Recast serious errors gently and praise successful communication.","target_phrases":["This is a book.","That is the board.","She is my classmate."]},"content":{"required_phrases":["This is a book.","That is the board."],"scenario":"Name five things in the classroom.","success_message":"Mission complete! You communicated successfully."},"estimated_seconds":180,"instructions":"Complete the mission with the AI partner.","order":9,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"source_activity":{"activity_id":"ACT_09","ai_config":{"allowed_vocabulary":["this","is","a","book","that","is","the","board","she","is","my","classmate"],"correction_style":"hint_first","difficulty_adjustment":"adaptive_by_confidence","learner_level":"A1","max_tur