INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('fcff7981-eeb4-5bf5-900e-bde389987a87', NULL, 'Listen and Do', 'Understand and follow simple classroom instructions.

The learner uses English in a realistic study situation focused on listen and do.', 6, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Open your book.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Open your book.","Please listen.","Write your name."],"points":10,"prompt":"Which phrase best helps you: understand and follow simple classroom instructions.","type":"multiple_choice"},{"answer":["Open your book.","Please listen.","Write your name."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Open your book.","Please listen.","Write your name."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Follow five spoken classroom instructions.","type":"recording"}],"final_task":{"learner_instruction":"Follow five spoken classroom instructions. Speak for at least 50 seconds.","minimum_seconds":50,"required_language":["Open your book.","Please listen."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Follow five spoken classroom instructions.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L07","lesson_number":7,"mission":"Understand and follow simple classroom instructions.","objectives":["Use key words and phrases to understand and follow simple classroom instructions.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on listen and do.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to understand and follow simple classroom instructions.","examples":["Open your book.","Please listen.","Write your name."],"pattern":"imperatives","point":"imperatives"}],"phrases":[{"audio_key":"a1_study_t01_l07_phrase_01","example":"Open your book.","formality":"neutral","phrase":"Open your book.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l07_phrase_02","example":"Please listen.","formality":"neutral","phrase":"Please listen.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l07_phrase_03","example":"Write your name.","formality":"neutral","phrase":"Write your name.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l07_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"Open your book.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l07_vocab_01","example":"I use the word ''open'' in this lesson.","image_key":"a1_study_t01_l07_vocab_01","meaning":"A key word used in this lesson: open.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''open''.","word":"open"},{"audio_key":"a1_study_t01_l07_vocab_02","example":"I use the word ''close'' in this lesson.","image_key":"a1_study_t01_l07_vocab_02","meaning":"A key word used in this lesson: close.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''close''.","word":"close"},{"audio_key":"a1_study_t01_l07_vocab_03","example":"I use the word ''listen'' in this lesson.","image_key":"a1_study_t01_l07_vocab_03","meaning":"A key word used in this lesson: listen.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''listen''.","word":"listen"},{"audio_key":"a1_study_t01_l07_vocab_04","example":"I use the word ''repeat'' in this lesson.","image_key":"a1_study_t01_l07_vocab_04","meaning":"A key word used in this lesson: repeat.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''repeat''.","word":"repeat"},{"audio_key":"a1_study_t01_l07_vocab_05","example":"I use the word ''write'' in this lesson.","image_key":"a1_study_t01_l07_vocab_05","meaning":"A key word used in this lesson: write.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''write''.","word":"write"}]},"title":"Listen and Do"}'::jsonb, NOW(), NOW())
