VALUES ('2879875b-6774-586f-a84f-379798b7ffad', 'fcff7981-eeb4-5bf5-900e-bde389987a87', 'text', 'See the Situation', '{"body":"<h2>Ситуация</h2><p>Вы в короткой учебной ситуации. Сначала послушайте модель, затем используйте ключевые слова и фразы этого урока.</p><p><strong>Ваша задача:</strong> понять ситуацию и подготовиться к короткому ответу по-английски.</p>","reading_time_minutes":1,"source_activity":{"activity_id":"ACT_02","content":{"story":"You are in a study situation. Your mission is: Understand and follow simple classroom instructions.","visual_brief":"A clear, friendly scene showing: Listen and Do."},"estimated_seconds":60,"instructions":"Read and listen to a very short situation.","order":2,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"success_criteria":["The learner identifies the people and setting."],"title":"See the Situation","type":"context_story"}}'::jsonb, 1, NOW(), NOW())
