g word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"Please repeat.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l08_vocab_01","example":"I use the word ''repeat'' in this lesson.","image_key":"a1_study_t01_l08_vocab_01","meaning":"A key word used in this lesson: repeat.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''repeat''.","word":"repeat"},{"audio_key":"a1_study_t01_l08_vocab_02","example":"I use the word ''again'' in this lesson.","image_key":"a1_study_t01_l08_vocab_02","meaning":"A key word used in this lesson: again.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''again''.","word":"again"},{"audio_key":"a1_study_t01_l08_vocab_03","example":"I use the word ''slowly'' in this lesson.","image_key":"a1_study_t01_l08_vocab_03","meaning":"A key word used in this lesson: slowly.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''slowly''.","word":"slowly"},{"audio_key":"a1_study_t01_l08_vocab_04","example":"I use the word ''understand'' in this lesson.","image_key":"a1_study_t01_l08_vocab_04","meaning":"A key word used in this lesson: understand.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''understand''.","word":"understand"},{"audio_key":"a1_study_t01_l08_vocab_05","example":"I use the word ''sorry'' in this lesson.","image_key":"a1_study_t01_l08_vocab_05","meaning":"A key word used in this lesson: sorry.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''sorry''.","word":"sorry"}]},"title":"Please Repeat"}'::jsonb, NOW(), NOW())
