INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('694a3710-d366-514c-a1e0-3c5fb5e4342a', NULL, 'First-Day Mission', 'Complete a full first-day classroom introduction.

The learner uses English in a realistic study situation focused on first-day mission.', 9, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Hello, everyone.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Hello, everyone.","My name is...","I am ready to learn."],"points":10,"prompt":"Which phrase best helps you: complete a full first-day classroom introduction.","type":"multiple_choice"},{"answer":["Hello, everyone.","My name is...","I am ready to learn."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Hello, everyone.","My name is...","I am ready to learn."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Introduce yourself for 30 to 60 seconds.","type":"recording"}],"final_task":{"learner_instruction":"Introduce yourself for 30 to 60 seconds. Speak for at least 65 seconds.","minimum_seconds":65,"required_language":["Hello, everyone.","My name is..."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Introduce yourself for 30 to 60 seconds.","task_type":"simulation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L10","lesson_number":10,"mission":"Complete a full first-day classroom introduction.","objectives":["Use key words and phrases to complete a full first-day classroom introduction.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on first-day mission.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to complete a full first-day classroom introduction.","examples":["Hello, everyone.","My name is...","I am ready to learn."],"pattern":"integrated review","point":"integrated review"}],"phrases":[{"audio_key":"a1_study_t01_l10_phrase_01","example":"Hello, everyone.","formality":"neutral","phrase":"Hello, everyone.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l10_phrase_02","example":"My name is...","formality":"neutral","phrase":"My name is...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l10_phrase_03","example":"I am ready to learn.","formality":"neutral","phrase":"I am ready to learn.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l10_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"Hello, everyone.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l10_vocab_01","example":"I use the word ''introduce'' in this lesson.","image_key":"a1_study_t01_l10_vocab_01","meaning":"A key word used in this lesson: introduce.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''introduce''.","word":"introduce"},{"audio_key":"a1_study_t01_l10_vocab_02","example":"I use the word ''remember'' in this lesson.","image_key":"a1_study_t01_l10_vocab_02","meaning":"A key word used in this lesson: remember.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''remember''.","word":"remember"},{"audio_key":"a1_study_t01_l10_vocab_03","example":"I use the word ''ready'' in this lesson.","image_key":"a1_study_t01_l10_vocab_03","meaning":"A key word used in this lesson: ready.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''ready''.","word":"ready"},{"audio_key":"a1_study_t01_l10_vocab_04","example":"I use the word ''start'' in this lesson.","image_key":"a1_study_t01_l10_vocab_04","meaning":"A key word used in this lesson: start.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''start''.","word":"start"},{"audio_key":"a1_study_t01_l10_vocab_05","example":"I use the word ''practice'' in this lesson.","image_key":"a1_study_t01_l10_vocab_05","meaning":"A key word used in this lesson: practice.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''practice''.","word":"practice"}]},"title":"First-Day Mission"}'::jsonb, NOW(), NOW())
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, order_index = EXCLUDED.order_index, source_metadata = EXCLUDED.source_metadata, updated_at = NOW();

INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('2eb5ccf9-1c91-51cb-bdca-e501e664712e', '694a3710-d366-514c-a1e0-3c5fb5e4342a', 'quiz', 'Speak Now', '{"activity_type":"warm_up","explanation":"«introduce» - одно из ключевых слов этого урока.","instruction":"Посмотрите на название урока и выберите слово, которое будете изучать.","options":[{"is_correct":true,"text":"introduce"},{"is_correct":false,"text":"remember"},{"is_correct":false,"text":"ready"},{"is_correct":false,"text":"start"}],"question":"Какое слово есть в названии урока «First-Day Mission»?","source_activity":{"activity_id":"ACT_01","content":{"prompt":"Look at the lesson title ''First-Day Mission''. What word do you already know?","sentence_frame":"I know ..."},"estimated_seconds":30,"instructions":"Answer one easy question using a word or short phrase.","order":1,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"success_criteria":["The learner produces one relevant word or short phrase."],"title":"Speak Now","type":"warm_up"}}'::jsonb, 0, NOW(), NOW())
ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, title = EXCLUDED.title, content = EXCLUDED.content, order_index = EXCLUDED.order_index, updated_at = NOW();

INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('267e3be5-291c-5c27-908b-f29f8238403e', '694a3710-d366-514c-a1e0-3c5fb5e4342a', 'text', 'See the Situation', '{"body":"<h2>Ситуация</h2><p>Вы в короткой учебной ситуации. Сначала послушайте модель, затем используйте ключевые слова и фразы этого урока.</p><p><strong>Ваша задача:</strong> понять ситуацию и подготовиться к короткому ответу по-английски.</p>","reading_time_minutes":1,"source_activity":{"activity_id":"ACT_02","content":{"story":"You are in a study situation. Your mission is: Complete a full first-day classroom introduction.","visual_brief":"A clear, friendly scene showing: First-Day Mission."},"estimated_seconds":60,"instructions":"Read and listen to a very short situation.","order":2,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"success_criteria":["The learner identifies the people and setting."],"title":"See the Situation","type":"context_story"}}'::jsonb, 1, NOW(), NOW())
