ssage":"Hello, everyone.","persona":"Warm, patient, encouraging, and concise. Use only beginner-friendly English.","role":"classmate or teacher in the lesson scenario","scoring_rubric":[{"criterion":"task_completion","description":"The learner completes the communication mission.","weight":0.4},{"criterion":"intelligibility","description":"The learner is understandable.","weight":0.3},{"criterion":"target_language","description":"The learner uses lesson words and phrases.","weight":0.3}],"system_prompt":"You are an A1 English speaking partner. Help the learner complete this mission: Introduce yourself for 30 to 60 seconds. Use short sentences, one question at a time, and familiar vocabulary. Do not give long grammar explanations. Recast serious errors gently and praise successful communication.","target_phrases":["Hello, everyone.","My name is...","I am ready to learn."]},"content":{"required_phrases":["Hello, everyone.","My name is..."],"scenario":"Introduce yourself for 30 to 60 seconds.","success_message":"Mission complete! You communicated successfully."},"estimated_seconds":180,"instructions":"Complete the mission with the AI partner.","order":9,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"success_criteria":["The learner completes the mission.","The learner uses at least two target phrases."],"title":"AI Speaking Mission","type":"ai_roleplay"},"success_criteria":["The learner completes the mission.","The learner uses at least two target phrases."],"target_phrases":["Hello, everyone.","My name is...","I am ready to learn."],"target_vocabulary":["introduce","remember","ready","start","practice"],"title":"AI Speaking Mission","type":"ai_roleplay"}'::jsonb, 8, NOW(), NOW())
